class ControlBar
{
public:
	void update(void);
	void updateContextMultiSelect(void);

private:
	char m_pad00[0x5C];
	Drawable *m_currentSelectedDrawable;
	char m_pad60[0x08];
	Real m_displayedConstructPercent;
	UnsignedInt m_displayedOCLTimerSeconds;
	UnsignedInt m_lastRecordedInventoryCount;
	char m_pad74[0x8C];
	GameWindow *m_commandWindows[MAX_COMMANDS_PER_SET];
	char m_pad150[0xA0];
	const CommandButton *m_commonCommands[MAX_COMMANDS_PER_SET];
	char m_pad1E0[0x18C];
	Int m_buildUpClockColor;
};

extern Real g_bfmeDefaultBU;
extern Real g_bfmeScaleBC;

void *GadgetButtonGetData(GameWindow *window);
void GadgetCheckLikeButtonSetVisualCheck(GameWindow *window, Bool checked);
void GadgetButtonDrawInverseClock(GameWindow *window, Int percent, Int color);

// The eight-way callee is the retail ControlBar::getCommandAvailability
// body at 0x004A4240, reached from this body through ILT 0x000414D4.
void ControlBar::updateContextMultiSelect(void)
{
	Drawable *draw;
	Object *obj;
	const CommandButton *command;
	GameWindow *win;
	Int objectsThatCanDoCommand[MAX_COMMANDS_PER_SET];
	Int i;

	if (m_currentSelectedDrawable != 0)
	{
		update();
		return;
	}

	for (i = 0; i < MAX_COMMANDS_PER_SET; ++i)
		objectsThatCanDoCommand[i] = 0;

	const BfmeControlBarDrawableList *selectedDrawables =
		((BfmeControlBarInGameUISelectionView *)TheInGameUI)->getAllSelectedDrawables();
	BfmeControlBarDrawableListNode *head = selectedDrawables->head;
	BfmeControlBarDrawableListNode *it = head->next;
	GameWindow **commandWindows = m_commandWindows;

	while (it != head)
	{
		draw = it->value;
		obj = draw->getObject();
		const ThingTemplate *thingTemplate = obj->getTemplate();
		if (thingTemplate->m_nextOverride != 0)
			thingTemplate = (const ThingTemplate *)thingTemplate->m_nextOverride->getFinalOverride();

		// Retail loads the full dword at +0xCC, then tests CH.  That is
		// the 0x00008000 ignored-in-GUI bit, not the 0x00800000 bit used
		// in the prior bank.
		if ((thingTemplate->getFlagsAtCC() & 0x00008000) != 0)
		{
			it = it->next;
			continue;
		}

		if (obj == 0)
		{
			it = it->next;
			continue;
		}

		for (i = 0; i < MAX_COMMANDS_PER_SET; ++i)
		{
			win = commandWindows[i];
			if (win == 0 || win->winIsHidden())
				continue;

			command = (const CommandButton *)GadgetButtonGetData(win);
			if (command == 0)
				continue;

			Real percent;
			Int availability =
				((const BfmeRva004A4240CommandAvailabilityView *)this)->call(
					command, win, obj, &percent, false);

			win->winClearStatus(0x00400000);
			win->winClearStatus(0x01000000);
			win->winClearStatus(0x40000000);
			win->winClearStatus(0x80000000);

			switch (availability)
			{
			case 0:
				win->winEnable(false);
				win->winSetStatus(0x80000000);
				break;

			case 1:
			case 2:
				win->winEnable(true);
				if (percent != g_bfmeDefaultBU)
					GadgetButtonDrawInverseClock(win,
						(Int)(percent * g_bfmeScaleBC), m_buildUpClockColor);
				break;

			case 3:
				win->winHide(true);
				break;

			case 4:
				win->winEnable(false);
				win->winSetStatus(0x00400000);
				break;

			case 5:
			case 6:
				win->winEnable(false);
				win->winSetStatus(0x01000000);
				break;

			case 7:
				win->winEnable(false);
				win->winSetStatus(0x80000000);
				win->winSetStatus(0x01000000);
				break;

			default:
				win->winEnable(true);
				if (percent != g_bfmeDefaultBU)
					GadgetButtonDrawInverseClock(win,
						(Int)(percent * g_bfmeScaleBC), m_buildUpClockColor);
				break;
			}

			if ((command->getOptions() & 0x400) != 0)
				GadgetCheckLikeButtonSetVisualCheck(win, availability == 2);

			if (availability == 1 || availability == 2)
				++objectsThatCanDoCommand[i];
		}

		it = it->next;
	}

	for (i = 0; i < MAX_COMMANDS_PER_SET; ++i)
	{
		win = commandWindows[i];
		if (win == 0 || win->winIsHidden() || m_commonCommands[i] == 0)
			continue;

		win->winEnable(objectsThatCanDoCommand[i] > 0);
	}
}
